// Interactive code tour. Data: window.VOX_TOUR from data.js (generated by
// scripts/gen-code-tour.py). Three widgets, each enabled by an element id:
//   #vt-map      crate map + crate details
//   #vt-explorer function explorer
//   #vt-flows    step-by-step walkthroughs
(function () {
  "use strict";
  const D = window.VOX_TOUR;
  if (!D) return;

  const FN = new Map(D.functions.map((f) => [f.id, f]));
  const CRATES = D.crates;
  const ORDER = { binary: ["vox"], core: [], adapter: [], sdk: [] };
  for (const [name, c] of Object.entries(CRATES)) {
    if (c.layer !== "binary") ORDER[c.layer].push(name);
  }
  ORDER.core.sort((a, b) => ["vox-editor", "vox-view", "vox-core"].indexOf(a) - ["vox-editor", "vox-view", "vox-core"].indexOf(b));

  // Plain-language explanation of each third-party library.
  const LIBS = {
    ropey: "keeps text as a “rope”: a balanced tree of small text chunks, so inserting or deleting in a large file does not copy the whole file",
    "unicode-width": "knows how many terminal cells each Unicode character takes (2 for Chinese/Japanese, 0 for combining accents)",
    arboard: "reads and writes the operating system clipboard (X11, Wayland, macOS, Windows)",
    crossterm: "controls the terminal: raw mode, key events, cursor movement and shape, text attributes",
    toml: "reads TOML, the simple settings-file format used by config.toml",
    wasmtime: "runs WebAssembly programs (the plugins) safely inside vox, with time and memory limits",
    "wasmtime-wasi": "gives plugins the minimal system interface Rust's standard library expects, with no files, network, or environment",
    "wit-bindgen": "generates the glue code between a Rust plugin and the vox plugin contract (wit/vox.wit)",
  };
  const LAYER_TEXT = {
    core: "core: std only, no third-party libraries",
    adapter: "adapter: wraps one third-party library behind a core trait",
    binary: "binary: wires adapters into the editor",
    sdk: "plugin SDK: used by plugin authors; compiled into plugins, not into vox",
  };

  // ---------- helpers ----------
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
  const md = (s) => esc(s).replace(/\[`([^`]+)`\]/g, "<code>$1</code>").replace(/`([^`]+)`/g, "<code>$1</code>");
  const h = (html) => { const t = document.createElement("template"); t.innerHTML = html.trim(); return t.content.firstElementChild; };
  const crateOf = (id) => id.split("::")[0];
  const qual = (id) => (FN.get(id) ? FN.get(id).qual : id.split("::").slice(1).join("::"));
  const srcUrl = (file, line) => {
    const m = file.match(/^crates\/([^/]+)\/src\/(.+)$/);
    return m ? `../api/src/${m[1].replace(/-/g, "_")}/${m[2]}.html#${line}` : "#";
  };
  const fnUrl = (id) => `functions.html#${encodeURIComponent(id)}`;
  const crateUrl = (name) => `index.html#crate=${encodeURIComponent(name)}`;
  const badge = (name) => `<span class="vt-badge vt-${CRATES[name].layer}">${esc(name)}</span>`;
  const firstSentence = (s) => (s.match(/^.*?[.!?](\s|$)/) || [s])[0].trim();
  const fnLink = (id, cls = "") => {
    const f = FN.get(id);
    const title = f ? esc(f.doc) : "";
    return `<a class="vt-link ${cls}" href="${fnUrl(id)}" title="${title}"><code>${esc(qual(id))}</code></a>`;
  };
  const flowsUsing = (id) => {
    const out = [];
    D.flows.forEach((fl) => fl.steps.forEach((st, i) => { if (st.fn === id) out.push([fl, i]); }));
    return out;
  };
  const traitDecl = (f) => f.trait && D.functions.find((g) => g.owner === f.trait && g.name === f.name && g.implemented_by);

  // Shared function card (explorer + walkthrough).
  function fnCard(f, { compact = false } = {}) {
    const vis = f.public ? "public" : "private";
    const where = f.trait ? `impl ${esc(f.trait)} for ${esc(f.owner)}` : f.owner ? `method of <code>${esc(f.owner)}</code>` : "free function";
    let html = `<div class="vt-card">
      <h3>${esc(f.qual)}</h3>
      <div class="vt-meta">
        <a href="${crateUrl(f.crate)}">${badge(f.crate)}</a>
        <span class="vt-muted">${vis} · ${where}</span>
        <a href="${srcUrl(f.file, f.line)}" title="Open source (requires the API docs build)">${esc(f.file)}:${f.line}</a>
      </div>
      <code class="vt-sig">${esc(f.sig)}</code>
      <div class="vt-doc">${f.doc ? md(f.doc) : '<span class="vt-muted">No description.</span>'}</div>`;
    if (f.implemented_by && f.implemented_by.length) {
      html += `<div class="vt-note">Trait method: the caller does not know which implementation runs. Implemented by: ${f.implemented_by.map((i) => fnLink(i)).join(", ")}</div>`;
    }
    const decl = traitDecl(f);
    if (decl) {
      html += `<div class="vt-note">Implements the trait method ${fnLink(decl.id)}. Callers go through the trait, so look at its callers: ${decl.called_by.length ? decl.called_by.map((i) => fnLink(i)).join(", ") : "none"}.</div>`;
    }
    if (compact) {
      html += `<p><a href="${fnUrl(f.id)}">Open in function explorer →</a></p></div>`;
      return html;
    }
    const list = (ids) => ids.length ? `<ul class="vt-list">${ids.map((i) => `<li>${fnLink(i)} <span class="vt-muted">${badge(crateOf(i))}</span></li>`).join("")}</ul>` : '<span class="vt-muted">none</span>';
    html += `<div class="vt-cols">
      <div><h4>Calls (${f.calls.length})</h4>${list(f.calls)}</div>
      <div><h4>Called by (${f.called_by.length})</h4>${list(f.called_by)}</div>
    </div>`;
    const used = flowsUsing(f.id);
    if (used.length) {
      html += `<h4>In walkthroughs</h4><ul class="vt-list">${used.map(([fl, i]) => `<li><a href="walkthroughs.html#flow=${fl.id}&step=${i + 1}">${esc(fl.title)}, step ${i + 1}</a></li>`).join("")}</ul>`;
    }
    html += `</div>`;
    return html;
  }

  // ---------- crate map ----------
  function crateMap(root) {
    const W = 900, NH = 58;
    const widest = Math.max(...Object.values(ORDER).map((l) => l.length));
    const NW = Math.min(170, W / widest - 14);
    const rows = { binary: 30, adapter: 165, core: 310 };
    const pos = {};
    for (const [layer, names] of Object.entries(ORDER)) {
      if (layer === "sdk") continue;
      const n = names.length;
      names.forEach((name, i) => {
        pos[name] = { x: (W / n) * (i + 0.5) - NW / 2, y: rows[layer] };
      });
    }
    // SDK crates sit top right: they are not part of the editor program.
    ORDER.sdk.forEach((name, i) => { pos[name] = { x: W - (NW + 10) * (i + 1), y: rows.binary }; });
    const edges = [];
    for (const [name, c] of Object.entries(CRATES)) {
      for (const d of c.deps) if (pos[d]) edges.push([name, d]);
    }
    const edgePath = (a, b) => {
      const p = pos[a], q = pos[b];
      if (p.y === q.y) {
        // same row: arc below the boxes
        const x1 = p.x + NW / 2, x2 = q.x + NW / 2, y = p.y + NH;
        return `M${x1},${y} C${x1},${y + 55} ${x2},${y + 55} ${x2},${y + 6}`;
      }
      const down = q.y > p.y;
      const x1 = p.x + NW / 2, y1 = down ? p.y + NH : p.y;
      const x2 = q.x + NW / 2, y2 = down ? q.y - 4 : q.y + NH + 4;
      const my = (y1 + y2) / 2;
      return `M${x1},${y1} C${x1},${my} ${x2},${my} ${x2},${y2}`;
    };
    const svg = `<svg viewBox="0 0 ${W} 440" role="img" aria-label="Crate dependency map">
      <defs><marker id="vt-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="currentColor"/></marker></defs>
      <rect class="band" x="0" y="290" width="${W}" height="140" rx="10"/>
      <text class="band-label" x="10" y="306">core — std only (the foundation everything else builds on)</text>
      <text class="band-label" x="10" y="155">adapters — one third-party library each</text>
      <text class="band-label" x="10" y="20">binary</text>
      ${ORDER.sdk.length ? `<text class="band-label" x="${W - NW - 10}" y="20">for plugin authors</text>` : ""}
      ${edges.map(([a, b]) => `<path class="edge" data-a="${a}" data-b="${b}" d="${edgePath(a, b)}" marker-end="url(#vt-arrow)" style="color:var(--fg)"/>`).join("")}
      ${Object.keys(pos).map((name) => {
        const c = CRATES[name], p = pos[name];
        const tp = c.third_party;
        const sub = tp.length ? `uses ${tp[0]}${tp.length > 1 ? ` +${tp.length - 1}` : ""}` : c.layer === "binary" ? "main()" : "std only";
        const fs = name.length > 13 ? 12 : 14;
        return `<g class="node ${c.layer}" data-crate="${name}" tabindex="0" transform="translate(${p.x},${p.y})">
          <rect width="${NW}" height="${NH}"/>
          <text x="${NW / 2}" y="25" text-anchor="middle" style="font-size:${fs}px">${esc(name)}</text>
          <text class="sub" x="${NW / 2}" y="44" text-anchor="middle">${esc(sub)}</text>
        </g>`;
      }).join("")}
    </svg>`;
    root.classList.add("vt", "vt-map");
    root.innerHTML = `<div class="vt-legend"><span class="vt-core">core (std only)</span><span class="vt-adapter">adapter (wraps a library)</span><span class="vt-binary">binary</span><span class="vt-sdk">plugin SDK</span><span class="vt-muted" style="color:inherit">arrow = “depends on”. Click a crate.</span></div>${svg}<div class="vt-panel" id="vt-crate-panel"></div>`;
    const panel = root.querySelector("#vt-crate-panel");

    function select(name) {
      if (!CRATES[name]) return;
      root.querySelectorAll(".node").forEach((n) => n.classList.toggle("sel", n.dataset.crate === name));
      root.querySelectorAll(".edge").forEach((e) => e.classList.toggle("hot", e.dataset.a === name || e.dataset.b === name));
      const c = CRATES[name];
      const fns = D.functions.filter((f) => f.crate === name);
      const pub = fns.filter((f) => f.public);
      const types = D.types.filter((t) => t.crate === name);
      const chips = (list) => list.length ? `<div class="vt-chips">${list.map((n) => `<a class="vt-link" data-crate="${n}">${badge(n)}</a>`).join("")}</div>` : '<span class="vt-muted">none</span>';
      const lib = c.third_party.map((l) => `<p><b>Library:</b> <code>${esc(l)}</code> — ${esc(LIBS[l] || "")}.</p>`).join("");
      const fnItem = (f) => `<li>${fnLink(f.id)} <span class="vt-muted">${md(firstSentence(f.doc))}</span></li>`;
      panel.innerHTML = `
        <h3>${badge(name)} <span class="vt-muted" style="font-weight:normal;font-size:0.8em">${esc(LAYER_TEXT[c.layer])}</span></h3>
        <p>${md(c.doc)}</p>${lib}
        <div class="vt-cols">
          <div><h4>Depends on</h4>${chips(c.deps)}</div>
          <div><h4>Used by</h4>${chips(c.used_by)}</div>
          <div><h4>Files</h4><ul class="vt-list">${c.files.map((f) => `<li><a href="${srcUrl(f.path, 1)}"><code>${esc(f.path.replace(/^crates\/[^/]+\//, ""))}</code></a> <span class="vt-muted">${f.lines} lines</span></li>`).join("")}</ul>
            <p><a href="../api/${name.replace(/-/g, "_")}/index.html">API reference (rustdoc) →</a></p></div>
        </div>
        <div class="vt-cols">
          <div><h4>Types (${types.length})</h4><ul class="vt-list">${types.map((t) => `<li><a href="${srcUrl(t.file, t.line)}" title="${esc(t.doc)}"><code>${esc(t.name)}</code></a> <span class="vt-muted">${t.kind}${t.public ? "" : ", private"} — ${md(firstSentence(t.doc))}</span></li>`).join("") || '<li class="vt-muted">none</li>'}</ul></div>
          <div><h4>Public functions (${pub.length} of ${fns.length})</h4><ul class="vt-list">${pub.map(fnItem).join("") || '<li class="vt-muted">none</li>'}</ul>
            <details><summary>Private functions (${fns.length - pub.length})</summary><ul class="vt-list">${fns.filter((f) => !f.public).map(fnItem).join("")}</ul></details>
            <p><a href="functions.html#crate=${encodeURIComponent(name)}">Explore these functions →</a></p></div>
        </div>`;
      panel.querySelectorAll("a[data-crate]").forEach((a) => a.addEventListener("click", () => select(a.dataset.crate)));
      history.replaceState(null, "", `#crate=${encodeURIComponent(name)}`);
    }

    root.querySelectorAll(".node").forEach((n) => {
      n.addEventListener("click", () => select(n.dataset.crate));
      n.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); select(n.dataset.crate); } });
    });
    const m = location.hash.match(/crate=([^&]+)/);
    select(m ? decodeURIComponent(m[1]) : "vox-editor");
  }

  // ---------- function explorer ----------
  function explorer(root) {
    root.classList.add("vt");
    const crateNames = Object.keys(CRATES);
    root.innerHTML = `<div class="vt-explorer">
      <div class="vt-side">
        <div class="vt-filters">
          <input type="search" placeholder="Search name or description…" aria-label="Search functions">
          <div>
            <select aria-label="Crate"><option value="">all crates</option>${crateNames.map((c) => `<option>${c}</option>`).join("")}</select>
            <label><input type="checkbox" class="pubonly"> public only</label>
          </div>
        </div>
        <div class="vt-count"></div>
        <div class="vt-items"></div>
      </div>
      <div class="vt-detail"></div>
    </div>
    <p class="vt-note">Calls are detected from the source text by <code>scripts/gen-code-tour.py</code>. Calls through
    trait objects are shown on the trait method (with links to its implementations). Closures may be missed.</p>`;
    const q = root.querySelector("input[type=search]");
    const sel = root.querySelector("select");
    const pubonly = root.querySelector(".pubonly");
    const items = root.querySelector(".vt-items");
    const count = root.querySelector(".vt-count");
    const detail = root.querySelector(".vt-detail");
    let current = null;

    function groupOf(f) {
      if (f.owner) return f.owner;
      const parts = f.qual.split("::");
      return parts.length > 1 ? parts[0] : "(crate root)";
    }
    function renderList() {
      const term = q.value.trim().toLowerCase();
      const list = D.functions.filter((f) =>
        (!sel.value || f.crate === sel.value) &&
        (!pubonly.checked || f.public) &&
        (!term || f.qual.toLowerCase().includes(term) || f.doc.toLowerCase().includes(term)));
      count.textContent = `${list.length} of ${D.functions.length} functions`;
      let html = "", last = "";
      for (const f of list) {
        const g = `${f.crate} · ${groupOf(f)}`;
        if (g !== last) { html += `<div class="vt-group">${esc(g)}</div>`; last = g; }
        html += `<button class="vt-item${f.id === current ? " sel" : ""}" data-id="${esc(f.id)}" title="${esc(f.doc)}"><span class="${f.public ? "" : "priv"}">${esc(f.name)}</span></button>`;
      }
      items.innerHTML = html || '<div class="vt-count">No matches.</div>';
    }
    function show(id, push = true) {
      const f = FN.get(id);
      if (!f) return;
      current = id;
      detail.innerHTML = fnCard(f);
      items.querySelectorAll(".vt-item").forEach((b) => b.classList.toggle("sel", b.dataset.id === id));
      const btn = items.querySelector(`.vt-item.sel`);
      if (btn) {
        const top = btn.offsetTop; // .vt-items is the offset parent
        if (top < items.scrollTop || top > items.scrollTop + items.clientHeight - btn.offsetHeight) {
          items.scrollTop = top - items.clientHeight / 3;
        }
      }
      if (push) history.replaceState(null, "", `#${encodeURIComponent(id)}`);
    }
    items.addEventListener("click", (e) => { const b = e.target.closest(".vt-item"); if (b) show(b.dataset.id); });
    detail.addEventListener("click", (e) => {
      const a = e.target.closest("a.vt-link");
      if (a && a.getAttribute("href").startsWith("functions.html#")) {
        e.preventDefault();
        const id = decodeURIComponent(a.getAttribute("href").split("#")[1]);
        if (sel.value && crateOf(id) !== sel.value) { sel.value = ""; renderList(); }
        show(id);
        detail.scrollIntoView({ block: "nearest" });
      }
    });
    [q, sel, pubonly].forEach((el) => el.addEventListener("input", renderList));

    function fromHash() {
      const raw = decodeURIComponent(location.hash.slice(1));
      if (raw.startsWith("crate=")) { sel.value = raw.slice(6); renderList(); const first = D.functions.find((f) => f.crate === sel.value); if (first) show(first.id, false); return; }
      renderList();
      show(FN.has(raw) ? raw : "vox-editor::Editor::handle_key", false);
    }
    window.addEventListener("hashchange", fromHash);
    fromHash();
  }

  // ---------- walkthroughs ----------
  function flows(root) {
    root.classList.add("vt");
    let flow = D.flows[0], step = 0;
    const allCrates = [...ORDER.binary, ...ORDER.core, ...ORDER.adapter];

    function render() {
      const st = flow.steps[step];
      const f = FN.get(st.fn);
      root.innerHTML = `
        <div class="vt-flowtabs">${D.flows.map((fl) => `<button data-flow="${fl.id}" class="${fl === flow ? "sel" : ""}">${md(fl.title)}</button>`).join("")}</div>
        <p><b>${md(flow.title)}</b> — ${md(flow.summary)}</p>
        <div class="vt-flow">
          <ol class="vt-steps">${flow.steps.map((s, i) => `<li><button data-step="${i}" class="${i === step ? "sel" : i < step ? "done" : ""}"><span class="fn">${esc(qual(s.fn))}</span></button></li>`).join("")}</ol>
          <div>
            <div class="vt-strip" title="Which crate this step runs in">${allCrates.map((c) => `<span class="vt-${CRATES[c].layer}${c === f.crate ? " on" : ""}">${esc(c)}</span>`).join("")}</div>
            <p class="vt-steptext"><b>Step ${step + 1} of ${flow.steps.length}.</b> ${md(st.text)}</p>
            ${fnCard(f, { compact: true })}
            <div class="vt-nav">
              <button class="prev" ${step === 0 ? "disabled" : ""}>← Previous</button>
              <button class="next" ${step === flow.steps.length - 1 ? "disabled" : ""}>Next →</button>
              <span class="vt-muted">Keys: ← →</span>
            </div>
          </div>
        </div>`;
      history.replaceState(null, "", `#flow=${flow.id}&step=${step + 1}`);
    }
    root.addEventListener("click", (e) => {
      const t = e.target.closest("button");
      if (!t) return;
      if (t.dataset.flow) { flow = D.flows.find((f) => f.id === t.dataset.flow); step = 0; }
      else if (t.dataset.step) step = +t.dataset.step;
      else if (t.classList.contains("prev")) step = Math.max(0, step - 1);
      else if (t.classList.contains("next")) step = Math.min(flow.steps.length - 1, step + 1);
      else return;
      render();
    });
    window.addEventListener("keydown", (e) => {
      if (e.target.closest("input, textarea, select") || e.altKey || e.ctrlKey || e.metaKey) return;
      if (e.key === "ArrowRight" && step < flow.steps.length - 1) { step++; render(); e.preventDefault(); e.stopPropagation(); }
      if (e.key === "ArrowLeft" && step > 0) { step--; render(); e.preventDefault(); e.stopPropagation(); }
    }, true);
    const m = location.hash.match(/flow=([^&]+)(?:&step=(\d+))?/);
    if (m) {
      flow = D.flows.find((f) => f.id === m[1]) || flow;
      step = Math.min(Math.max(0, (+m[2] || 1) - 1), flow.steps.length - 1);
    }
    render();
  }

  const go = () => {
    const map = document.getElementById("vt-map");
    const ex = document.getElementById("vt-explorer");
    const fl = document.getElementById("vt-flows");
    if (map) crateMap(map);
    if (ex) explorer(ex);
    if (fl) flows(fl);
  };
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", go);
  else go();
})();
